import Foundation

/// The small C runtime written into a homebrew project's `source/generated/` whenever a UI or node
/// graph is present: a software renderer into the Wii's YUY2 framebuffer (rects, bitmap-font text,
/// images), Wii Remote pointer + A-button clicks, and the app hooks the node editor fills in.
nonisolated enum WiiUIRuntime {
    static let header = #"""
    /* wiiui.h: generated by Revolution Editor. Do not edit; changes are overwritten on build. */
    #ifndef WIIUI_H
    #define WIIUI_H

    #include <gccore.h>
    #include <wiiuse/wpad.h>
    #include "wgfx.h"

    extern const int wiiui_screen_w;        /* 640, or 854 for a 16:9 design */
    #define WIIUI_WIDTH  wiiui_screen_w
    #define WIIUI_HEIGHT 480

    enum { WIIUI_RECT, WIIUI_LABEL, WIIUI_BUTTON, WIIUI_IMAGE };

    typedef struct { short x, y, w, h, xoff, yoff, advance; } wiiui_glyph;      /* x, y: position in the atlas */
    typedef struct { int size, lineHeight, ascent; wgfx_texture atlas; wiiui_glyph glyphs[95]; } wiiui_font;   /* ASCII 32..126 */
    typedef struct { const unsigned char *pcm; unsigned int bytes; unsigned int rate; } wiiui_sound;           /* 16-bit mono, big-endian */

    typedef struct {
        int kind;
        int x, y, w, h;
        unsigned char fill[3];      /* rect/button fill */
        unsigned char color[3];     /* text colour */
        char text[128];
        const wiiui_font *font;
        int sprite;                 /* IMAGE: index into wiiui_sprites, or -1 */
        int visible;
    } wiiui_widget;

    extern wiiui_widget wiiui_widgets[];
    extern const int wiiui_widget_count;
    typedef struct { int first, count; unsigned char background[3]; } wiiui_screen;      /* a range of wiiui_widgets */
    extern const wiiui_screen wiiui_screens[];
    extern const int wiiui_screen_count;
    void wn_actors_update(void);                        /* sprite actors (actors_generated.c) */
    void wn_actors_draw(void);
    void wiiui_set_fps(int fps);                        /* 60 by default; 30, 20, 15... run slower and lighter */
    int  wiiui_fps(void);
    void wiiui_show_screen(int screen);                 /* switch to another UI screen (SCREEN_<NAME>) */
    int  wiiui_current_screen(void);
    extern const wiiui_font *const wiiui_fonts[];
    extern const int wiiui_font_count;
    extern wgfx_texture wiiui_sprites[];
    extern const int wiiui_sprite_count;
    typedef struct { const unsigned char *data; unsigned int size; } wiiui_music;                             /* a .brstm file */
    extern const wiiui_sound wiiui_sounds[];
    extern const wiiui_music wiiui_musics[];
    extern const int wiiui_music_count;
    extern const int wiiui_sound_count;

    void wiiui_init(void);
    int  wiiui_frame(void);                         /* one frame; returns 0 once HOME is pressed */

    /* Widgets (from the UI designer) */
    void wiiui_set_text(int id, const char *text);
    const char *wiiui_get_text(int id);
    void wiiui_set_visible(int id, int visible);
    void wiiui_set_color(int id, int r, int g, int b);  /* text colour for labels, fill otherwise */
    void wiiui_show_cursor(int visible);
    unsigned wiiui_frame_count(void);

    /* Drawing: call from app_on_draw. Coordinates are the 640x480 (or 854x480) screen, y down. Colours 0..255. */
    void wiiui_draw_rect(int x, int y, int w, int h, int r, int g, int b, int a);
    void wiiui_draw_text(int size, int x, int y, const char *text, int r, int g, int b, int a);   /* y = top of the line */
    int  wiiui_text_width(int size, const char *text);
    int  wiiui_font_height(int size);                  /* line height of the nearest available size */
    void wiiui_draw_sprite(int sprite, int x, int y);
    void wiiui_draw_sprite_ex(int sprite, int x, int y, int w, int h, int flip_x, int flip_y, int alpha);
    void wiiui_draw_sprite_region(int sprite, int sx, int sy, int sw, int sh, int x, int y, int w, int h);
    int  wiiui_sprite_width(int sprite);
    int  wiiui_sprite_height(int sprite);

    /* Input: WPAD_BUTTON_* masks. A GameCube pad or Classic Controller on the same player number
       counts as the Wii Remote (D-pad = D-pad, A/B = A/B, X = 1, Y = 2, Start/+ = +, Z/- = -). */
    unsigned wiiui_held(int player);
    unsigned wiiui_pressed(int player);
    float wiiui_stick_x(int player);                /* -1..1: Nunchuk, Classic left stick or GameCube stick; right = +1 */
    float wiiui_stick_y(int player);                /* up = +1 */
    int   wiiui_pointer(int *x, int *y);            /* Wii Remote 1 pointer in screen coordinates; 0 if off screen */

    /* Sound */
    void wiiui_play_sound(int sound);
    void wiiui_play_music(int music, int loop);          /* streams a .brstm from assets/; loop: 1 = use the file's loop point */
    void wiiui_stop_music(void);
    int  wiiui_music_playing(void);
    void wiiui_music_volume(int volume);                 /* 0..255 */
    void wiiui_play_sound_volume(int sound, int volume);   /* 0..255 */

    int  wiiui_rects_overlap(int ax, int ay, int aw, int ah, int bx, int by, int bw, int bh);

    /* Per-frame scratch memory (cleared at the start of every frame) and an on-screen log. */
    void *wiiui_arena_alloc(unsigned int size);
    void wiiui_log(const char *line);
    void wiiui_show_log(int visible);

    /* Hooks. The node editor and Swift translator generate these; in C, define the ones you need. */
    void app_on_start(void);
    void app_on_frame(void);                        /* update: once per frame, before drawing */
    void app_on_draw(void);                         /* draw: between the background and the UI widgets */
    void app_on_button(int id);
    void app_on_wpad(unsigned int pressed);

    #endif

    """#

    static let gfxHeader = #"""
    /* wgfx.h: generated by Revolution Editor. Do not edit; changes are overwritten on build. */
    #ifndef WGFX_H
    #define WGFX_H

    #define WGFX_RGB5A3 0
    #define WGFX_IA8    1

    /* A texture already in the GameCube/Wii's 4x4-tiled 16-bit format (data is 32-byte aligned). */
    typedef struct {
        const unsigned char *data;
        short w, h;                 /* size in texels */
        short pw, ph;               /* padded to whole 4x4 tiles */
        unsigned char format;
        unsigned char smooth;       /* 1 = bilinear when scaled */
        unsigned char ready;
        unsigned int obj[8];        /* GXTexObj, filled on first use */
    } wgfx_texture;

    void wgfx_init(int game_w);
    void wgfx_begin(int r, int g, int b);                       /* start a frame, cleared to a colour */
    /* A textured, tinted rectangle; t == NULL draws a solid colour. u/v are 0..1 across the padded texture. */
    void wgfx_quad(wgfx_texture *t, float x, float y, float w, float h, float u0, float v0, float u1, float v1,
                   int r, int g, int b, int a);
    void wgfx_end(void);                                        /* finish the frame and show it */
    void wgfx_set_fps(int fps);                                 /* frames per second to run at (60 or a divisor of it) */
    void wgfx_screen_to_game(int sx, int sy, int *gx, int *gy); /* pointer position -> game screen */
    void wgfx_screen_size(int *w, int *h);

    #endif

    """#

    /// The GX backend: everything that touches the Wii's graphics hardware lives here.
    static let gfxSourceGX = #"""
    /* wgfx_gx.c: generated by Revolution Editor. Do not edit; changes are overwritten on build. */
    #include <gccore.h>
    #include <malloc.h>
    #include <string.h>
    #include "wgfx.h"

    #define FIFO_SIZE (256 * 1024)

    _Static_assert(sizeof(GXTexObj) <= sizeof(((wgfx_texture *)0)->obj), "wgfx_texture.obj is too small for a GXTexObj");

    static void *xfb[2] = { NULL, NULL };
    static int fb = 0;
    static GXRModeObj *rmode;
    static void *fifo;
    static int wide = 0;                    /* 16:9 TV. A screen of another shape is pillar- or letterboxed so circles stay round */
    static int game_w = 640;
    static int view_x, view_y, view_w, view_h;      /* EFB */
    static int vsyncs_per_frame = 1;
    static int sview_y, sview_h;                    /* the same band in framebuffer rows */
    static wgfx_texture *bound = NULL;

    /* One white texel (RGB5A3, opaque white), used for solid rectangles. */
    static unsigned char white_data[32] __attribute__((aligned(32)));
    static wgfx_texture white_tex = { white_data, 4, 4, 4, 4, WGFX_RGB5A3, 0, 0, { 0 } };

    void wgfx_init(int gw) {
        game_w = gw;
        VIDEO_Init();
        CONF_Init();
        rmode = VIDEO_GetPreferredMode(NULL);
        wide = CONF_GetAspectRatio() == CONF_ASPECT_16_9;
        float tv_aspect = wide ? 16.0f / 9 : 4.0f / 3, game_aspect = (float)game_w / 480;
        view_x = 0; view_y = 0; view_w = rmode->fbWidth; view_h = rmode->efbHeight;
        if (game_aspect < tv_aspect) { view_w = (int)(rmode->fbWidth * game_aspect / tv_aspect); view_x = (rmode->fbWidth - view_w) / 2; }
        else if (game_aspect > tv_aspect) { view_h = (int)(rmode->efbHeight * tv_aspect / game_aspect); view_y = (rmode->efbHeight - view_h) / 2; }
        sview_y = view_y * rmode->xfbHeight / rmode->efbHeight;
        sview_h = view_h * rmode->xfbHeight / rmode->efbHeight;

        xfb[0] = MEM_K0_TO_K1(SYS_AllocateFramebuffer(rmode));
        xfb[1] = MEM_K0_TO_K1(SYS_AllocateFramebuffer(rmode));
        VIDEO_Configure(rmode);
        VIDEO_SetNextFramebuffer(xfb[fb]);
        VIDEO_SetBlack(FALSE);
        VIDEO_Flush();
        VIDEO_WaitVSync();
        if (rmode->viTVMode & VI_NON_INTERLACE) VIDEO_WaitVSync();
        fb ^= 1;

        fifo = memalign(32, FIFO_SIZE);
        memset(fifo, 0, FIFO_SIZE);
        GX_Init(fifo, FIFO_SIZE);

        GXColor black = { 0, 0, 0, 255 };
        GX_SetCopyClear(black, GX_MAX_Z24);
        GX_SetViewport(view_x, view_y, view_w, view_h, 0, 1);
        f32 yscale = GX_GetYScaleFactor(rmode->efbHeight, rmode->xfbHeight);
        u32 xfbHeight = GX_SetDispCopyYScale(yscale);
        GX_SetScissor(view_x, view_y, view_w, view_h);
        GX_SetDispCopySrc(0, 0, rmode->fbWidth, rmode->efbHeight);
        GX_SetDispCopyDst(rmode->fbWidth, xfbHeight);
        GX_SetCopyFilter(rmode->aa, rmode->sample_pattern, GX_TRUE, rmode->vfilter);
        GX_SetFieldMode(rmode->field_rendering, ((rmode->viHeight == 2 * rmode->xfbHeight) ? GX_ENABLE : GX_DISABLE));
        if (rmode->aa) GX_SetPixelFmt(GX_PF_RGB565_Z16, GX_ZC_LINEAR);
        else GX_SetPixelFmt(GX_PF_RGB8_Z24, GX_ZC_LINEAR);
        GX_SetCullMode(GX_CULL_NONE);
        GX_CopyDisp(xfb[fb], GX_TRUE);
        GX_SetDispCopyGamma(GX_GM_1_0);

        /* Vertices: position, colour, texture coordinate. One texture stage, modulated by the colour. */
        GX_ClearVtxDesc();
        GX_SetVtxDesc(GX_VA_POS, GX_DIRECT);
        GX_SetVtxDesc(GX_VA_CLR0, GX_DIRECT);
        GX_SetVtxDesc(GX_VA_TEX0, GX_DIRECT);
        GX_SetVtxAttrFmt(GX_VTXFMT0, GX_VA_POS, GX_POS_XYZ, GX_F32, 0);
        GX_SetVtxAttrFmt(GX_VTXFMT0, GX_VA_CLR0, GX_CLR_RGBA, GX_RGBA8, 0);
        GX_SetVtxAttrFmt(GX_VTXFMT0, GX_VA_TEX0, GX_TEX_ST, GX_F32, 0);
        GX_SetNumChans(1);
        GX_SetNumTexGens(1);
        GX_SetTevOp(GX_TEVSTAGE0, GX_MODULATE);
        GX_SetTevOrder(GX_TEVSTAGE0, GX_TEXCOORD0, GX_TEXMAP0, GX_COLOR0A0);
        GX_SetTexCoordGen(GX_TEXCOORD0, GX_TG_MTX2x4, GX_TG_TEX0, GX_IDENTITY);
        GX_SetBlendMode(GX_BM_BLEND, GX_BL_SRCALPHA, GX_BL_INVSRCALPHA, GX_LO_CLEAR);

        GX_InvVtxCache();
        GX_InvalidateTexAll();

        /* 2D: one unit = one pixel of the game screen, y down. */
        Mtx view;
        guMtxIdentity(view);
        guMtxTransApply(view, view, 0.0f, 0.0f, -5.0f);
        GX_LoadPosMtxImm(view, GX_PNMTX0);
        Mtx44 proj;
        guOrtho(proj, 0, 480, 0, game_w, 0, 300);
        GX_LoadProjectionMtx(proj, GX_ORTHOGRAPHIC);

        for (int i = 0; i < 16; i++) ((unsigned short *)white_data)[i] = 0xFFFF;
    }

    void wgfx_begin(int r, int g, int b) {
        GX_SetZMode(GX_FALSE, GX_ALWAYS, GX_FALSE);
        bound = NULL;
        wgfx_quad(NULL, 0, 0, game_w, 480, 0, 0, 1, 1, r, g, b, 255);
    }

    static void bind(wgfx_texture *t) {
        if (t == bound) return;
        GXTexObj *o = (GXTexObj *)t->obj;
        if (!t->ready) {
            int fmt = t->format == WGFX_IA8 ? GX_TF_IA8 : GX_TF_RGB5A3;
            GX_InitTexObj(o, (void *)t->data, t->pw, t->ph, fmt, GX_CLAMP, GX_CLAMP, GX_FALSE);
            GX_InitTexObjFilterMode(o, t->smooth ? GX_LINEAR : GX_NEAR, t->smooth ? GX_LINEAR : GX_NEAR);
            DCFlushRange((void *)t->data, (u32)t->pw * t->ph * 2);
            t->ready = 1;
        }
        GX_LoadTexObj(o, GX_TEXMAP0);
        bound = t;
    }

    void wgfx_quad(wgfx_texture *t, float x, float y, float w, float h, float u0, float v0, float u1, float v1,
                   int r, int g, int b, int a) {
        bind(t ? t : &white_tex);
        GX_Begin(GX_QUADS, GX_VTXFMT0, 4);
        GX_Position3f32(x, y, 0);         GX_Color4u8(r, g, b, a); GX_TexCoord2f32(u0, v0);
        GX_Position3f32(x + w, y, 0);     GX_Color4u8(r, g, b, a); GX_TexCoord2f32(u1, v0);
        GX_Position3f32(x + w, y + h, 0); GX_Color4u8(r, g, b, a); GX_TexCoord2f32(u1, v1);
        GX_Position3f32(x, y + h, 0);     GX_Color4u8(r, g, b, a); GX_TexCoord2f32(u0, v1);
        GX_End();
    }

    void wgfx_end(void) {
        GX_DrawDone();
        fb ^= 1;
        GX_SetZMode(GX_TRUE, GX_LEQUAL, GX_TRUE);
        GX_SetColorUpdate(GX_TRUE);
        GX_CopyDisp(xfb[fb], GX_TRUE);
        VIDEO_SetNextFramebuffer(xfb[fb]);
        VIDEO_Flush();
        for (int i = 0; i < vsyncs_per_frame; i++) VIDEO_WaitVSync();
    }

    void wgfx_set_fps(int fps) {
        int hz = VIDEO_GetCurrentTvMode() == VI_PAL ? 50 : 60;
        vsyncs_per_frame = fps <= 0 ? 1 : (hz + fps / 2) / fps;
        if (vsyncs_per_frame < 1) vsyncs_per_frame = 1;
    }

    void wgfx_screen_to_game(int sx, int sy, int *gx, int *gy) {
        *gx = (sx - view_x) * game_w / view_w;
        *gy = (sy - sview_y) * 480 / sview_h;
    }

    void wgfx_screen_size(int *w, int *h) { *w = rmode->fbWidth; *h = rmode->xfbHeight; }

    """#

    static let source = #"""
    /* wiiui.c: generated by Revolution Editor. Do not edit; changes are overwritten on build. */
    #include <math.h>
    #include <stdlib.h>
    #include <string.h>
    #include <asndlib.h>
    #include "wiiui.h"

    __attribute__((weak)) const int wiiui_fps_setting = 60;      /* overridden by a node graph's frame rate */
    static int cur_fps = 60;
    void wiiui_set_fps(int fps) { if (fps < 1) fps = 60; cur_fps = fps; wgfx_set_fps(fps); }
    int wiiui_fps(void) { return cur_fps; }
    __attribute__((weak)) void wn_actors_update(void) {}
    __attribute__((weak)) void wn_actors_draw(void) {}
    __attribute__((weak)) void app_on_start(void) {}
    __attribute__((weak)) void app_on_frame(void) {}
    __attribute__((weak)) void app_on_draw(void) {}
    __attribute__((weak)) void app_on_button(int id) { (void)id; }
    __attribute__((weak)) void app_on_wpad(unsigned int pressed) { (void)pressed; }

    #define PLAYERS 4
    #define MASK_ALL (WPAD_BUTTON_A | WPAD_BUTTON_B | WPAD_BUTTON_1 | WPAD_BUTTON_2 | WPAD_BUTTON_PLUS | WPAD_BUTTON_MINUS | \
                      WPAD_BUTTON_HOME | WPAD_BUTTON_UP | WPAD_BUTTON_DOWN | WPAD_BUTTON_LEFT | WPAD_BUTTON_RIGHT)

    static unsigned frames = 0;
    static unsigned held[PLAYERS], pressed[PLAYERS];
    static float stick_x[PLAYERS], stick_y[PLAYERS];
    static int cursor_x = -100, cursor_y = -100, cursor_valid = 0;
    static int cursor_mode = -1;            /* -1 = show only when the UI has buttons */
    static int held_id = -1;
    static int cur_screen = 0;
    /* The frame is opened before any hook runs, so drawing from app_on_frame / app_on_button also shows. */
    static int frame_open = 0;
    static void begin_frame(void) {
        const unsigned char *bg = wiiui_screens[cur_screen].background;
        wgfx_begin(bg[0], bg[1], bg[2]);
        frame_open = 1;
    }
    void wiiui_show_screen(int s) {
        if (s < 0 || s >= wiiui_screen_count) return;
        cur_screen = s; held_id = -1;
        if (frame_open) begin_frame();      /* new background for what is drawn next */
    }
    int wiiui_current_screen(void) { return cur_screen; }
    #define SCR_FIRST (wiiui_screens[cur_screen].first)
    #define SCR_END (wiiui_screens[cur_screen].first + wiiui_screens[cur_screen].count)

    unsigned wiiui_frame_count(void) { return frames; }
    unsigned wiiui_held(int p) { return p >= 0 && p < PLAYERS ? held[p] : 0; }
    unsigned wiiui_pressed(int p) { return p >= 0 && p < PLAYERS ? pressed[p] : 0; }
    float wiiui_stick_x(int p) { return p >= 0 && p < PLAYERS ? stick_x[p] : 0; }
    float wiiui_stick_y(int p) { return p >= 0 && p < PLAYERS ? stick_y[p] : 0; }
    int wiiui_pointer(int *x, int *y) { if (x) *x = cursor_x; if (y) *y = cursor_y; return cursor_valid; }
    void wiiui_show_cursor(int visible) { cursor_mode = visible != 0; }
    int wiiui_rects_overlap(int ax, int ay, int aw, int ah, int bx, int by, int bw, int bh) {
        return ax < bx + bw && bx < ax + aw && ay < by + bh && by < ay + ah;
    }

    void wiiui_set_text(int id, const char *text) {
        if (id < 0 || id >= wiiui_widget_count) return;
        strncpy(wiiui_widgets[id].text, text, sizeof(wiiui_widgets[id].text) - 1);
        wiiui_widgets[id].text[sizeof(wiiui_widgets[id].text) - 1] = 0;
    }
    const char *wiiui_get_text(int id) { return (id < 0 || id >= wiiui_widget_count) ? "" : wiiui_widgets[id].text; }
    void wiiui_set_visible(int id, int visible) { if (id >= 0 && id < wiiui_widget_count) wiiui_widgets[id].visible = visible != 0; }
    void wiiui_set_color(int id, int r, int g, int b) {
        if (id < 0 || id >= wiiui_widget_count) return;
        unsigned char *c = wiiui_widgets[id].kind == WIIUI_LABEL ? wiiui_widgets[id].color : wiiui_widgets[id].fill;
        c[0] = r < 0 ? 0 : r > 255 ? 255 : r; c[1] = g < 0 ? 0 : g > 255 ? 255 : g; c[2] = b < 0 ? 0 : b > 255 ? 255 : b;
    }

    /* ---- scratch memory and log ---- */
    static unsigned char arena[320 * 1024] __attribute__((aligned(16)));
    static unsigned arena_used = 0;

    void *wiiui_arena_alloc(unsigned int size) {
        size = (size + 15) & ~15u;
        if (arena_used + size > sizeof arena) exit(1);
        void *p = &arena[arena_used];
        arena_used += size;
        memset(p, 0, size);
        return p;
    }

    #define LOG_LINES 14
    static char log_lines[LOG_LINES][96];
    static int log_count = 0, log_visible = 0;
    void wiiui_show_log(int visible) { log_visible = visible != 0; }
    void wiiui_log(const char *line) {
        if (log_count == LOG_LINES) { memmove(log_lines[0], log_lines[1], sizeof(log_lines[0]) * (LOG_LINES - 1)); log_count--; }
        strncpy(log_lines[log_count], line, sizeof(log_lines[0]) - 1);
        log_lines[log_count][sizeof(log_lines[0]) - 1] = 0;
        log_count++;
    }

    /* ---- drawing ---- */
    void wiiui_draw_rect(int x, int y, int w, int h, int r, int g, int b, int a) {
        wgfx_quad(NULL, x, y, w, h, 0, 0, 1, 1, r, g, b, a);
    }

    static const wiiui_font *font_for(int size) {
        const wiiui_font *best = NULL;
        int bestd = 1 << 30;
        for (int i = 0; i < wiiui_font_count; i++) {
            int d = abs(wiiui_fonts[i]->size - size);
            if (d < bestd) { bestd = d; best = wiiui_fonts[i]; }
        }
        return best;
    }

    static int text_width(const wiiui_font *f, const char *s) {
        int w = 0;
        for (; *s; s++) if (*s >= 32 && *s <= 126) w += f->glyphs[*s - 32].advance;
        return w;
    }

    static void draw_text(const wiiui_font *f, int x, int y, const char *s, int r, int g, int b, int a) {
        if (!f) return;
        wgfx_texture *at = (wgfx_texture *)&f->atlas;
        for (; *s; s++) {
            if (*s < 32 || *s > 126) continue;
            const wiiui_glyph *gl = &f->glyphs[*s - 32];
            if (gl->w > 0)
                wgfx_quad(at, x + gl->xoff, y + gl->yoff, gl->w, gl->h,
                          (float)gl->x / at->pw, (float)gl->y / at->ph, (float)(gl->x + gl->w) / at->pw, (float)(gl->y + gl->h) / at->ph,
                          r, g, b, a);
            x += gl->advance;
        }
    }

    void wiiui_draw_text(int size, int x, int y, const char *text, int r, int g, int b, int a) { draw_text(font_for(size), x, y, text, r, g, b, a); }
    int wiiui_text_width(int size, const char *text) { const wiiui_font *f = font_for(size); return f ? text_width(f, text) : 0; }
    int wiiui_font_height(int size) { const wiiui_font *f = font_for(size); return f ? f->lineHeight : size; }

    int wiiui_sprite_width(int s) { return s >= 0 && s < wiiui_sprite_count ? wiiui_sprites[s].w : 0; }
    int wiiui_sprite_height(int s) { return s >= 0 && s < wiiui_sprite_count ? wiiui_sprites[s].h : 0; }

    void wiiui_draw_sprite_region(int s, int sx, int sy, int sw, int sh, int x, int y, int w, int h) {
        if (s < 0 || s >= wiiui_sprite_count) return;
        wgfx_texture *t = &wiiui_sprites[s];
        wgfx_quad(t, x, y, w, h, (float)sx / t->pw, (float)sy / t->ph, (float)(sx + sw) / t->pw, (float)(sy + sh) / t->ph, 255, 255, 255, 255);
    }

    void wiiui_draw_sprite_ex(int s, int x, int y, int w, int h, int flip_x, int flip_y, int alpha) {
        if (s < 0 || s >= wiiui_sprite_count) return;
        wgfx_texture *t = &wiiui_sprites[s];
        float u0 = 0, u1 = (float)t->w / t->pw, v0 = 0, v1 = (float)t->h / t->ph, tmp;
        if (flip_x) { tmp = u0; u0 = u1; u1 = tmp; }
        if (flip_y) { tmp = v0; v0 = v1; v1 = tmp; }
        wgfx_quad(t, x, y, w, h, u0, v0, u1, v1, 255, 255, 255, alpha);
    }

    void wiiui_draw_sprite(int s, int x, int y) { wiiui_draw_sprite_ex(s, x, y, wiiui_sprite_width(s), wiiui_sprite_height(s), 0, 0, 255); }

    /* ---- sound ---- */
    /* ---- Music: streams a .brstm (PCM8, PCM16 or DSP-ADPCM; the first two channels) through one ASND voice ---- */
    typedef struct {
    const unsigned char *d;
    unsigned size, total, loop_start, audio, blocks, block_size, block_samples, final_size, final_samples, final_padded, pos;
    int codec, channels, rate, looping, ok;
    int coef[2][16], h1[2], h2[2], loop_h1[2], loop_h2[2];
    } wm_state;

    static unsigned wm_u32(const unsigned char *p) { return ((unsigned)p[0] << 24) | (p[1] << 16) | (p[2] << 8) | p[3]; }
    static int wm_s16(const unsigned char *p) { return (short)((p[0] << 8) | p[1]); }
    static int wm_in(const wm_state *m, unsigned off, unsigned len) { return off <= m->size && len <= m->size - off; }

    /* Reads a big-endian BRSTM (PCM8, PCM16 or DSP-ADPCM) held in memory. The first two channels are played. */
    static void wm_open(wm_state *m, const unsigned char *d, unsigned size) {
    memset(m, 0, sizeof *m);
    m->d = d; m->size = size;
    if (size < 0x40 || memcmp(d, "RSTM", 4) != 0 || d[4] != 0xFE || d[5] != 0xFF) return;
    unsigned head = wm_u32(d + 0x10);
    if (!wm_in(m, head, 0x20) || memcmp(d + head, "HEAD", 4) != 0) return;
    unsigned hb = head + 8, si = hb + wm_u32(d + hb + 4);
    if (!wm_in(m, si, 0x2C)) return;
    m->codec = d[si]; m->looping = d[si + 1] != 0; m->channels = d[si + 2];
    m->rate = (d[si + 3] << 16) | (d[si + 4] << 8) | d[si + 5];
    m->loop_start = wm_u32(d + si + 0x08); m->total = wm_u32(d + si + 0x0C); m->audio = wm_u32(d + si + 0x10);
    m->blocks = wm_u32(d + si + 0x14); m->block_size = wm_u32(d + si + 0x18); m->block_samples = wm_u32(d + si + 0x1C);
    m->final_size = wm_u32(d + si + 0x20); m->final_samples = wm_u32(d + si + 0x24); m->final_padded = wm_u32(d + si + 0x28);
    if (m->codec > 2 || m->channels < 1 || m->channels > 32 || m->block_samples == 0 || m->blocks == 0 || m->total == 0) return;
    if (m->codec == 2) {
        unsigned ct = hb + wm_u32(d + hb + 0x14);
        for (int c = 0; c < (m->channels < 2 ? 1 : 2); c++) {
            unsigned ref = ct + 4 + c * 8;
            if (!wm_in(m, ref, 8)) return;
            unsigned ind = hb + wm_u32(d + ref + 4);
            if (!wm_in(m, ind, 8)) return;
            unsigned po = hb + wm_u32(d + ind + 4);
            if (!wm_in(m, po, 0x2E)) return;
            for (int i = 0; i < 16; i++) m->coef[c][i] = wm_s16(d + po + i * 2);
            m->h1[c] = wm_s16(d + po + 0x24); m->h2[c] = wm_s16(d + po + 0x26);
            m->loop_h1[c] = wm_s16(d + po + 0x2A); m->loop_h2[c] = wm_s16(d + po + 0x2C);
        }
    }
    m->ok = 1;
    }

    static int wm_clamp(int v) { return v < -32768 ? -32768 : (v > 32767 ? 32767 : v); }

    /* One sample of channel c at m->pos; ADPCM history advances, so call in order for every pos. */
    static int wm_sample(wm_state *m, int c) {
    unsigned blk = m->pos / m->block_samples, in = m->pos % m->block_samples;
    int last = blk == m->blocks - 1;
    unsigned base = m->audio + blk * m->channels * m->block_size + c * (last ? m->final_padded : m->block_size);
    const unsigned char *d = m->d;
    if (m->codec == 1) return wm_in(m, base + in * 2, 2) ? wm_s16(d + base + in * 2) : 0;
    if (m->codec == 0) return wm_in(m, base + in, 1) ? (signed char)d[base + in] * 256 : 0;
    unsigned fr = base + in / 14 * 8;
    if (!wm_in(m, fr, 8)) return 0;
    int scale = 1 << (d[fr] & 15), ci = d[fr] >> 4, k = in % 14;
    if (ci > 7) ci = 7;
    int nib = (k & 1) ? (d[fr + 1 + k / 2] & 15) : (d[fr + 1 + k / 2] >> 4);
    if (nib >= 8) nib -= 16;
    int s = ((nib * scale) << 11);
    s = wm_clamp((s + 1024 + m->coef[c][ci * 2] * m->h1[c] + m->coef[c][ci * 2 + 1] * m->h2[c]) >> 11);
    m->h2[c] = m->h1[c]; m->h1[c] = s;
    return s;
    }

    /* Fills up to `frames` interleaved stereo frames; returns how many (fewer only when a non-looping stream ends). */
    static int wm_read(wm_state *m, short *out, int frames, int loop) {
    int n = 0;
    while (n < frames) {
        if (m->pos >= m->total) {
            if (!(loop && m->looping) || m->loop_start >= m->total) break;
            m->pos = m->loop_start;
            for (int c = 0; c < 2; c++) { m->h1[c] = m->loop_h1[c]; m->h2[c] = m->loop_h2[c]; }
        }
        int l = wm_sample(m, 0), r = m->channels > 1 ? wm_sample(m, 1) : l;
        out[n * 2] = (short)l; out[n * 2 + 1] = (short)r;
        m->pos++; n++;
    }
    return n;
    }

    #define MUSIC_FRAMES 4096
    static wm_state music;
    static short music_buf[2][MUSIC_FRAMES * 2] __attribute__((aligned(32)));
    static int music_voice = -1, music_loop = 0, music_vol = 255, music_next = 1, music_ended = 0, music_tail = 0;
    /* A voice only stays alive between buffers (and reports "ready") when it has a callback. */
    static void music_cb(s32 voice) { (void)voice; }

    static int music_fill(int b) {
        int n = wm_read(&music, music_buf[b], MUSIC_FRAMES, music_loop);
        if (n < MUSIC_FRAMES) memset(music_buf[b] + n * 2, 0, (MUSIC_FRAMES - n) * 4);
        DCFlushRange(music_buf[b], sizeof music_buf[b]);
        return n;
    }

    void wiiui_stop_music(void) {
        if (music_voice >= 0) ASND_StopVoice(music_voice);
        music_voice = -1; music_tail = 0;
    }

    void wiiui_play_music(int id, int loop) {
        wiiui_stop_music();
        if (id < 0 || id >= wiiui_music_count || !wiiui_musics[id].data) return;
        wm_open(&music, wiiui_musics[id].data, wiiui_musics[id].size);
        if (!music.ok) return;
        int v = ASND_GetFirstUnusedVoice();
        if (v < 0) return;
        music_loop = loop;
        music_ended = music_fill(0) < MUSIC_FRAMES;
        music_next = 1; music_tail = 0;
        ASND_SetVoice(v, VOICE_STEREO_16BIT, music.rate, 0, music_buf[0], sizeof music_buf[0], music_vol, music_vol, music_cb);
        music_voice = v;
    }

    int wiiui_music_playing(void) { return music_voice >= 0; }
    void wiiui_music_volume(int v) {
        music_vol = v < 0 ? 0 : (v > 255 ? 255 : v);
        if (music_voice >= 0) ASND_ChangeVolumeVoice(music_voice, music_vol, music_vol);
    }

    /* Once a frame: queue the next chunk whenever the voice is waiting for one. */
    static void music_update(void) {
        if (music_voice < 0) return;
        if (music_tail) { if (--music_tail == 0) wiiui_stop_music(); return; }
        if (ASND_StatusVoice(music_voice) == SND_UNUSED) { music_voice = -1; return; }
        if (!ASND_TestVoiceBufferReady(music_voice)) return;     /* both buffers still queued */
        if (music_ended) { music_tail = 10; return; }            /* the last (partial) buffer has started; let it finish */
        music_ended = music_fill(music_next) < MUSIC_FRAMES;
        ASND_AddVoice(music_voice, music_buf[music_next], sizeof music_buf[music_next]);
        music_next ^= 1;
    }

    void wiiui_play_sound_volume(int s, int volume) {
        if (s < 0 || s >= wiiui_sound_count || wiiui_sounds[s].bytes == 0) return;
        int v = ASND_GetFirstUnusedVoice();
        if (v < 0) return;
        if (volume < 0) volume = 0;
        if (volume > 255) volume = 255;
        DCFlushRange((void *)wiiui_sounds[s].pcm, wiiui_sounds[s].bytes);
        ASND_SetVoice(v, VOICE_MONO_16BIT, wiiui_sounds[s].rate, 0, (void *)wiiui_sounds[s].pcm, wiiui_sounds[s].bytes, volume, volume, NULL);
    }
    void wiiui_play_sound(int s) { wiiui_play_sound_volume(s, 255); }

    /* ---- input ---- */
    static float axis(float mag, float ang, int want_y) {
        float rad = ang * 3.14159265f / 180.0f;
        return want_y ? mag * cosf(rad) : mag * sinf(rad);
    }

    static unsigned poll_player(int c, float *sx, float *sy) {
        unsigned m = 0;
        *sx = *sy = 0;
        u32 h = WPAD_ButtonsHeld(c);
        m |= h & MASK_ALL;
        WPADData *d = WPAD_Data(c);
        if (d && d->err == WPAD_ERR_NONE) {
            if (d->exp.type == WPAD_EXP_NUNCHUK) {
                *sx = axis(d->exp.nunchuk.js.mag, d->exp.nunchuk.js.ang, 0);
                *sy = axis(d->exp.nunchuk.js.mag, d->exp.nunchuk.js.ang, 1);
            } else if (d->exp.type == WPAD_EXP_CLASSIC) {
                if (h & WPAD_CLASSIC_BUTTON_UP) m |= WPAD_BUTTON_UP;
                if (h & WPAD_CLASSIC_BUTTON_DOWN) m |= WPAD_BUTTON_DOWN;
                if (h & WPAD_CLASSIC_BUTTON_LEFT) m |= WPAD_BUTTON_LEFT;
                if (h & WPAD_CLASSIC_BUTTON_RIGHT) m |= WPAD_BUTTON_RIGHT;
                if (h & WPAD_CLASSIC_BUTTON_A) m |= WPAD_BUTTON_A;
                if (h & WPAD_CLASSIC_BUTTON_B) m |= WPAD_BUTTON_B;
                if (h & WPAD_CLASSIC_BUTTON_X) m |= WPAD_BUTTON_1;
                if (h & WPAD_CLASSIC_BUTTON_Y) m |= WPAD_BUTTON_2;
                if (h & WPAD_CLASSIC_BUTTON_PLUS) m |= WPAD_BUTTON_PLUS;
                if (h & WPAD_CLASSIC_BUTTON_MINUS) m |= WPAD_BUTTON_MINUS;
                *sx = axis(d->exp.classic.ljs.mag, d->exp.classic.ljs.ang, 0);
                *sy = axis(d->exp.classic.ljs.mag, d->exp.classic.ljs.ang, 1);
            }
        }
        u16 g = PAD_ButtonsHeld(c);
        if (g & PAD_BUTTON_UP) m |= WPAD_BUTTON_UP;
        if (g & PAD_BUTTON_DOWN) m |= WPAD_BUTTON_DOWN;
        if (g & PAD_BUTTON_LEFT) m |= WPAD_BUTTON_LEFT;
        if (g & PAD_BUTTON_RIGHT) m |= WPAD_BUTTON_RIGHT;
        if (g & PAD_BUTTON_A) m |= WPAD_BUTTON_A;
        if (g & PAD_BUTTON_B) m |= WPAD_BUTTON_B;
        if (g & PAD_BUTTON_X) m |= WPAD_BUTTON_1;
        if (g & PAD_BUTTON_Y) m |= WPAD_BUTTON_2;
        if (g & PAD_BUTTON_START) m |= WPAD_BUTTON_PLUS;
        if (g & PAD_TRIGGER_Z) m |= WPAD_BUTTON_MINUS;
        float gx = PAD_StickX(c) / 80.0f, gy = PAD_StickY(c) / 80.0f;
        if (fabsf(gx) > 0.15f || fabsf(gy) > 0.15f) { *sx = gx > 1 ? 1 : gx < -1 ? -1 : gx; *sy = gy > 1 ? 1 : gy < -1 ? -1 : gy; }
        return m;
    }

    static void poll_input(void) {
        WPAD_ScanPads();
        PAD_ScanPads();
        for (int c = 0; c < PLAYERS; c++) {
            unsigned prev = held[c];
            held[c] = poll_player(c, &stick_x[c], &stick_y[c]);
            pressed[c] = held[c] & ~prev;
        }
        ir_t ir;
        WPAD_IR(0, &ir);
        cursor_valid = ir.valid != 0;
        if (cursor_valid) wgfx_screen_to_game((int)ir.x, (int)ir.y, &cursor_x, &cursor_y);
    }

    /* ---- widgets ---- */
    static unsigned char lift(int v, int d) { v += d; return (unsigned char)(v < 0 ? 0 : v > 255 ? 255 : v); }

    static int hit(const wiiui_widget *w) {
        return cursor_valid && cursor_x >= w->x && cursor_x < w->x + w->w && cursor_y >= w->y && cursor_y < w->y + w->h;
    }

    static void draw_widget(int id) {
        const wiiui_widget *w = &wiiui_widgets[id];
        if (!w->visible) return;
        switch (w->kind) {
        case WIIUI_RECT:
            wiiui_draw_rect(w->x, w->y, w->w, w->h, w->fill[0], w->fill[1], w->fill[2], 255);
            break;
        case WIIUI_IMAGE:
            if (w->sprite >= 0) wiiui_draw_sprite_ex(w->sprite, w->x, w->y, w->w, w->h, 0, 0, 255);
            else wiiui_draw_rect(w->x, w->y, w->w, w->h, w->fill[0], w->fill[1], w->fill[2], 255);
            break;
        case WIIUI_LABEL:
            if (w->font) draw_text(w->font, w->x, w->y + (w->h - w->font->lineHeight) / 2, w->text, w->color[0], w->color[1], w->color[2], 255);
            break;
        case WIIUI_BUTTON: {
            int d = hit(w) ? (held_id == id ? -30 : 30) : 0;
            wiiui_draw_rect(w->x, w->y, w->w, w->h, lift(w->fill[0], 60), lift(w->fill[1], 60), lift(w->fill[2], 60), 255);
            wiiui_draw_rect(w->x + 2, w->y + 2, w->w - 4, w->h - 4, lift(w->fill[0], d), lift(w->fill[1], d), lift(w->fill[2], d), 255);
            if (w->font) {
                int tw = text_width(w->font, w->text);
                draw_text(w->font, w->x + (w->w - tw) / 2, w->y + (w->h - w->font->lineHeight) / 2, w->text, w->color[0], w->color[1], w->color[2], 255);
            }
            break;
        }
        }
    }

    void wiiui_init(void) {
        wgfx_init(wiiui_screen_w);
        wiiui_set_fps(wiiui_fps_setting);
        WPAD_Init();
        PAD_Init();
        for (int c = 0; c < PLAYERS; c++) WPAD_SetDataFormat(c, WPAD_FMT_BTNS_ACC_IR);
        int w, h;
        wgfx_screen_size(&w, &h);
        WPAD_SetVRes(0, w, h);
        ASND_Init();
        ASND_Pause(0);
        app_on_start();
    }

    int wiiui_frame(void) {
        arena_used = 0;
        music_update();
        poll_input();
        if (WPAD_ButtonsDown(0) & WPAD_BUTTON_HOME) return 0;
        begin_frame();
        if (pressed[0] & WPAD_BUTTON_A) {
            held_id = -1;
            for (int i = SCR_END - 1; i >= SCR_FIRST; i--)   /* topmost first */
                if (wiiui_widgets[i].kind == WIIUI_BUTTON && wiiui_widgets[i].visible && hit(&wiiui_widgets[i])) { held_id = i; break; }
            if (held_id >= 0) app_on_button(held_id);
        } else if (!(held[0] & WPAD_BUTTON_A)) held_id = -1;
        for (int c = 0; c < PLAYERS; c++) if (pressed[c]) app_on_wpad(pressed[c]);
        app_on_frame();
        wn_actors_update();

        app_on_draw();
        wn_actors_draw();
        for (int i = SCR_FIRST; i < SCR_END; i++) draw_widget(i);
        int any_button = 0;
        for (int i = SCR_FIRST; i < SCR_END; i++) if (wiiui_widgets[i].kind == WIIUI_BUTTON) any_button = 1;
        if (cursor_valid && (cursor_mode < 0 ? any_button : cursor_mode)) {
            wiiui_draw_rect(cursor_x - 8, cursor_y - 1, 17, 3, 0, 0, 0, 255);
            wiiui_draw_rect(cursor_x - 1, cursor_y - 8, 3, 17, 0, 0, 0, 255);
            wiiui_draw_rect(cursor_x - 7, cursor_y, 15, 1, 255, 255, 255, 255);
            wiiui_draw_rect(cursor_x, cursor_y - 7, 1, 15, 255, 255, 255, 255);
        }
        if (log_visible) {
            wiiui_draw_rect(0, 0, wiiui_screen_w, 8 + log_count * 18, 0, 0, 0, 170);
            for (int i = 0; i < log_count; i++) wiiui_draw_text(16, 6, 4 + i * 18, log_lines[i], 120, 255, 120, 255);
        }
        wgfx_end();
        frame_open = 0;
        frames++;
        return 1;
    }

    """#

    /// Support functions the node editor's generated logic calls (rotating text buffers, random).
    static let nodeSupport = #"""
    #define WN_UNUSED __attribute__((unused))
    static char wn_bufs[8][256];
    static int wn_next = 0;

    static WN_UNUSED char *wn_buf(void) { char *b = wn_bufs[wn_next]; wn_next = (wn_next + 1) & 7; return b; }

    static WN_UNUSED const char *wn_num_text(double v) {
        char *b = wn_buf();
        if (v == (double)(long long)v) snprintf(b, 256, "%lld", (long long)v);
        else snprintf(b, 256, "%.2f", v);
        return b;
    }

    typedef struct { int r, g, b; } wn_col;
    typedef struct { double x, y, w, h; } wn_bounds;
    static WN_UNUSED wn_bounds wn_bounds_make(double x, double y, double w, double h) { wn_bounds b = { x, y, w, h }; return b; }
    typedef struct { double x, y; } wn_vec;
    static WN_UNUSED wn_bounds wn_bounds_from_vecs(wn_vec p, wn_vec s) { return wn_bounds_make(p.x, p.y, s.x, s.y); }
    static WN_UNUSED const char *wn_bool_text(int v) { return v ? "Yes" : "No"; }
    static WN_UNUSED const char *wn_vec_text(wn_vec v) {
        char x[32], y[32];
        if (v.x == (double)(long long)v.x) snprintf(x, sizeof x, "%lld", (long long)v.x); else snprintf(x, sizeof x, "%.2f", v.x);
        if (v.y == (double)(long long)v.y) snprintf(y, sizeof y, "%lld", (long long)v.y); else snprintf(y, sizeof y, "%.2f", v.y);
        char *b = wn_buf();
        snprintf(b, 256, "%s, %s", x, y);
        return b;
    }
    static WN_UNUSED const char *wn_col_text(wn_col c) {
        char *b = wn_buf();
        snprintf(b, 256, "%d, %d, %d", c.r, c.g, c.b);
        return b;
    }

    static WN_UNUSED const char *wn_join(const char *a, const char *b2) {
        char *b = wn_buf();
        snprintf(b, 256, "%s%s", a, b2);
        return b;
    }

    static WN_UNUSED double wn_random(double lo, double hi) {
        if (hi < lo) { double t = lo; lo = hi; hi = t; }
        return lo + (double)(rand() % 1000001) / 1000000.0 * (hi - lo);
    }

    static WN_UNUSED double wn_div(double a, double b) { return b == 0 ? 0 : a / b; }
    static WN_UNUSED double wn_abs(double a) { return a < 0 ? -a : a; }
    static WN_UNUSED double wn_min(double a, double b) { return a < b ? a : b; }
    static WN_UNUSED double wn_max(double a, double b) { return a > b ? a : b; }
    static WN_UNUSED double wn_pointer(int axis) { int x = -100, y = -100; wiiui_pointer(&x, &y); return axis ? y : x; }
    static WN_UNUSED int wn_c8(double v) { return v < 0 ? 0 : (v > 255 ? 255 : (int)v); }
    static WN_UNUSED wn_col wn_col_make(double r, double g, double b) { wn_col c = { wn_c8(r), wn_c8(g), wn_c8(b) }; return c; }
    static WN_UNUSED wn_vec wn_vec_make(double x, double y) { wn_vec v = { x, y }; return v; }
    static WN_UNUSED wn_vec wn_vec_add(wn_vec a, wn_vec b) { return wn_vec_make(a.x + b.x, a.y + b.y); }
    static WN_UNUSED wn_vec wn_vec_sub(wn_vec a, wn_vec b) { return wn_vec_make(a.x - b.x, a.y - b.y); }
    static WN_UNUSED wn_vec wn_vec_scale(wn_vec a, double k) { return wn_vec_make(a.x * k, a.y * k); }
    static WN_UNUSED double wn_vec_len(wn_vec a) { return sqrt(a.x * a.x + a.y * a.y); }
    static WN_UNUSED double wn_mod(double a, double b) { return b == 0 ? 0 : (double)((long long)a % (long long)b); }

    """#

    /// `wn.h`: what the node editor's generated logic includes.
    static var nodeHeader: String {
        "/* wn.h, generated by Revolution Editor. Do not edit. */\n#ifndef WN_H\n#define WN_H\n#include \"wiiui.h\"\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <math.h>\n\n" + nodeSupport + "#endif\n"
    }

    /// `ws.h`: value-type strings and helpers for Swift-translated code. `wn_str` is a 128-byte
    /// value, so strings copy like Swift's do and nothing dangles.
    static let swiftSupport = #"""
    /* ws.h: generated by Revolution Editor. Do not edit. */
    #ifndef WS_H
    #define WS_H
    #include <stdio.h>
    #include <stdlib.h>
    #include <string.h>
    #include <math.h>

    #include "wiiui.h"

    #define WS_UNUSED __attribute__((unused))
    typedef struct { char s[128]; } wn_str;

    static WS_UNUSED wn_str ws_lit(const char *t) { wn_str r; strncpy(r.s, t, 127); r.s[127] = 0; return r; }
    static WS_UNUSED wn_str ws_join(wn_str a, wn_str b) {
        wn_str r;
        strncpy(r.s, a.s, 127); r.s[127] = 0;
        strncat(r.s, b.s, 127 - strlen(r.s));
        return r;
    }
    static WS_UNUSED wn_str ws_num(double v) {
        wn_str r;
        if (v == (double)(long long)v) snprintf(r.s, sizeof r.s, "%lld", (long long)v);
        else snprintf(r.s, sizeof r.s, "%.2f", v);
        return r;
    }
    static WS_UNUSED int ws_pointer(int axis) { int x = -100, y = -100; wiiui_pointer(&x, &y); return axis ? y : x; }
    static WS_UNUSED int ws_eq(wn_str a, wn_str b) { return strcmp(a.s, b.s) == 0; }
    /* Stops the app, as a Swift runtime error would (array index, force unwrap, divide by zero). */
    static WS_UNUSED void ws_fatal(void) { exit(1); }
    #define ws_idiv(a, b) ({ __typeof__(a) _a = (a); __typeof__(b) _b = (b); if (_b == 0) ws_fatal(); _a / _b; })
    #define ws_imod(a, b) ({ __typeof__(a) _a = (a); __typeof__(b) _b = (b); if (_b == 0) ws_fatal(); _a % _b; })
    static WS_UNUSED wn_str ws_upper(wn_str a) { for (char *p = a.s; *p; p++) if (*p >= 'a' && *p <= 'z') *p -= 32; return a; }
    static WS_UNUSED wn_str ws_lower(wn_str a) { for (char *p = a.s; *p; p++) if (*p >= 'A' && *p <= 'Z') *p += 32; return a; }
    static WS_UNUSED int ws_hasPrefix(wn_str a, wn_str b) { return strncmp(a.s, b.s, strlen(b.s)) == 0; }
    static WS_UNUSED int ws_hasSuffix(wn_str a, wn_str b) { size_t la = strlen(a.s), lb = strlen(b.s); return lb <= la && strcmp(a.s + la - lb, b.s) == 0; }
    static WS_UNUSED int ws_contains(wn_str a, wn_str b) { return strstr(a.s, b.s) != NULL; }
    static WS_UNUSED double ws_random_double(double lo, double hi) { return lo + (double)(rand() % 1000001) / 1000000.0 * (hi - lo); }
    /* Out-of-range array indexes stop the app instead of corrupting memory. */
    static WS_UNUSED int ws_idx(int i, int n) { if (i < 0 || i >= n) ws_fatal(); return i; }
    static WS_UNUSED int ws_iabs(int x) { return x < 0 ? -x : x; }
    static WS_UNUSED double ws_dabs(double x) { return x < 0 ? -x : x; }
    static WS_UNUSED int ws_imin(int a, int b) { return a < b ? a : b; }
    static WS_UNUSED int ws_imax(int a, int b) { return a > b ? a : b; }
    static WS_UNUSED double ws_dmin(double a, double b) { return a < b ? a : b; }
    static WS_UNUSED double ws_dmax(double a, double b) { return a > b ? a : b; }
    static WS_UNUSED int ws_random_int(int lo, int hi) {
        if (hi < lo) { int t = lo; lo = hi; hi = t; }
        return lo + rand() % (hi - lo + 1);
    }
